<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { controlAvance, descargarAvance, opcionesAvance, type EmpresaAvance } from '../services/bgc'
const periods=ref<string[]>([]),companies=ref<Array<{id:number;nombre:string}>>([]),period=ref(''),selected=ref<number[]>([]),results=ref<EmpresaAvance[]>([]),loading=ref(false),error=ref('')
const average=computed(()=>results.value.length?Math.round(results.value.reduce((sum,item)=>sum+percentage(item),0)/results.value.length):0)
function percentage(item:EmpresaAvance){return item.total?Math.round(item.aprobados*100/item.total):0}
async function init(){try{const data=await opcionesAvance();periods.value=data.periodos;companies.value=data.empresas;period.value=data.periodos[0]||'';selected.value=data.empresas.map(item=>item.id);await load()}catch(cause){error.value=message(cause)}}
async function load(){if(!period.value)return;loading.value=true;try{results.value=await controlAvance(period.value,selected.value)}catch(cause){error.value=message(cause)}finally{loading.value=false}}
async function download(item:EmpresaAvance){try{await descargarAvance(item.id,period.value)}catch(cause){error.value=message(cause)}}
function message(cause:unknown){return cause instanceof Error?cause.message:'No se pudo cargar el control de avance.'}
onMounted(init)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Institucional / Buen Gobierno / Control de avance</nav><header class="hero"><div class="mark">BGC</div><div><small>Buen Gobierno Corporativo</small><h1>Control de avance</h1><p>Compara el cumplimiento de criterios y evidencias por empresa.</p></div><div class="global"><b>{{average}}%</b><span>avance promedio</span></div></header><p v-if="error" class="error">{{error}}</p><section class="filters"><label>Periodo<select v-model="period"><option v-for="item in periods" :key="item">{{item}}</option></select></label><fieldset><legend>Empresas</legend><label v-for="item in companies" :key="item.id"><input v-model="selected" type="checkbox" :value="item.id"> {{item.nombre}}</label></fieldset><button @click="load">Consultar avance</button></section><div v-if="loading" class="empty">Calculando avance…</div><div v-else-if="!results.length" class="empty">No se encontraron resultados para los filtros seleccionados.</div><section v-else class="cards"><article v-for="item in results" :key="item.id"><header><div><small>Empresa</small><h2>{{item.nombre}}</h2></div><button @click="download(item)">Descargar resumen</button></header><div class="progress"><div :style="{width:`${percentage(item)}%`}"></div></div><div class="score"><b>{{percentage(item)}}%</b><span>{{item.aprobados}} de {{item.total}} criterios aprobados</span></div><div class="metrics"><div><b>{{item.cargados}}</b><span>Cargados</span></div><div class="approved"><b>{{item.aprobados}}</b><span>Aprobados</span></div><div class="observed"><b>{{item.observados}}</b><span>Observados</span></div><div><b>{{item.pendientes}}</b><span>Pendientes</span></div></div><section class="criteria"><div v-for="criterion in item.criterios" :key="criterion.tipo"><span>{{criterion.tipo}}</span><div class="bar"><i :style="{width:`${criterion.avance}%`}"></i></div><b>{{criterion.avance}}%</b></div></section></article></section></div></template>
